import type {
  Request,
  Response,
  NextFunction,
} from "express";
import multer from "multer";

interface RequestError extends Error {
  status?: number;
  statusCode?: number;
  type?: string;
}

export function errorHandler(
  error: unknown,
  _req: Request,
  res: Response,
  _next: NextFunction
): void {
  if (res.headersSent) {
    return;
  }

  // Handle file-upload errors generated by Multer.
  if (error instanceof multer.MulterError) {
    if (error.code === "LIMIT_FILE_SIZE") {
      res.status(413).json({
        success: false,
        message: "Resume file exceeds the 5 MB limit.",
      });
      return;
    }

    res.status(400).json({
      success: false,
      message: "Invalid file upload request.",
    });
    return;
  }

  const requestError = error as RequestError;

  // Handle the file filter's PDF validation error.
  if (requestError.message === "Only PDF files are allowed.") {
    res.status(400).json({
      success: false,
      message: "Only PDF files are allowed.",
    });
    return;
  }

  // Handle oversized request bodies.
  if (
    requestError.type === "entity.too.large" ||
    requestError.status === 413 ||
    requestError.statusCode === 413
  ) {
    res.status(413).json({
      success: false,
      message: "Request body is too large.",
    });
    return;
  }

  // Handle invalid JSON.
  if (requestError.type === "entity.parse.failed") {
    res.status(400).json({
      success: false,
      message: "Invalid JSON request body.",
    });
    return;
  }

  console.error("Unhandled request error:", error);

  res.status(500).json({
    success: false,
    message: "Internal server error.",
  });
}
